const checkDomRemoval = function (mutations) {
  const isFocusedNodeRemoved = mutations.some(function (mutation) {
    const removedNodes = Array.from(mutation.removedNodes);
    return removedNodes.some(function (node) {
      return node === state.mostRecentlyFocusedNode;
    });
  });

  // Also check if the focused node is no longer connected (e.g., removed as a descendant)
  const focusedNodeDisconnected = state.mostRecentlyFocusedNode && 
    (typeof state.mostRecentlyFocusedNode.isConnected === 'boolean' 
      ? !state.mostRecentlyFocusedNode.isConnected 
      : !doc.contains(state.mostRecentlyFocusedNode));

  // If the currently focused is removed then browsers will move focus to the
  // <body> element. If this happens, try to move focus back into the trap.
  if (isFocusedNodeRemoved || focusedNodeDisconnected) {
    tryFocus(getInitialFocusNode());
  }
};

if (nextNode) {
  tryFocus(nextNode);
} else {
  const mruNode = state.mostRecentlyFocusedNode;
  if (mruNode && mruNode.isConnected && isFocusable(mruNode, config.tabbableOptions)) {
    tryFocus(mruNode);
  } else {
    tryFocus(getInitialFocusNode());
  }
}
